import { writeFileSync } from "node:fs";
import path from "node:path";
import { stringify } from "yaml";
import { buildOpenApiDocument } from "../src/lib/openapi/document";

/** Writes the committed snapshot of the API contract. Run: npm run openapi */
const target = path.join(process.cwd(), "docs/api/openapi.yaml");
const header =
  "# Generated by `npm run openapi` from src/lib/openapi/document.ts. Do not edit.\n";
writeFileSync(
  target,
  header + stringify(JSON.parse(JSON.stringify(buildOpenApiDocument()))),
);
process.stdout.write(`Wrote ${path.relative(process.cwd(), target)}\n`);
